const input = items[0].json || {};
const folderPath = String(input.folderPath || input.folder_path || '').replace(/^\/+|\/+$/g, '').replace(/\s+\/\s+/g, '/');
const fileName = String(input.fileName || input.file_name || `report-${Date.now()}.txt`).replace(/[\\/:*?"<>|]/g, '-');
const content = String(input.fileContent || input.file_content || input.text || '');
const encodedFolder = folderPath.split('/').map(encodeURIComponent).join('/');
return [{ json: { ...input, folderPath, fileName, content, graphUrl: `https://graph.microsoft.com/v1.0/me/drive/root:/${encodedFolder}/${encodeURIComponent(fileName)}:/content` } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const input = $('Prepare Graph Request').item.json;
const f = items[0].json || {};
if (f.error || !f.id) return fail('WF_SAVE_REPORT_TO_SELECTED_ONEDRIVE_FOLDER', f.error || f.message || 'Report was not saved');
return pass(`Report saved to selected OneDrive folder.\nFile name: ${f.name || input.fileName}\nType: file\nSize: ${f.size || 0}\nFolder path: ${input.folderPath}\nLink: ${f.webUrl || ''}\nVerification status: Passed`, { file: f, folderPath: input.folderPath });
